import subprocess, json, unicodedata, random, sys
EXE="/workspace/executable"
def probe(key):
    inp=json.dumps({key:1},ensure_ascii=False)
    r=subprocess.run([EXE],input=inp.encode(),capture_output=True)
    out=r.stdout.decode('utf-8',errors='replace')
    kline=out.strip().split('\n')[-1]
    return kline.startswith('json.')

FIRST_OK={'Lu','Ll','Lm','Lo','Nl'}
REST_OK=FIRST_OK|{'Mn','Mc','Nd','Pc'}
def pred_first(ch):
    return ch in '$_' or unicodedata.category(ch) in FIRST_OK
def pred_rest(ch):
    return ch in '$_' or unicodedata.category(ch) in REST_OK

random.seed(42)
cps=list(range(0x20,0x3000))+[random.randrange(0x3000,0x110000) for _ in range(4000)]
bad=0; tested=0
for cp in cps:
    if 0xD800<=cp<=0xDFFF: continue
    ch=chr(cp)
    try: key_ok=json.dumps(ch)
    except: continue
    tested+=1
    # first position
    got=probe(ch)
    exp=pred_first(ch)
    if got!=exp:
        bad+=1
        if bad<=30: print(f"FIRST MISMATCH U+{cp:04X} {unicodedata.name(ch,'?')} cat={unicodedata.category(ch)} got_bare={got} exp_bare={exp}")
    # rest position
    got=probe('a'+ch)
    exp=pred_rest(ch)
    if got!=exp:
        bad+=1
        if bad<=30: print(f"REST MISMATCH U+{cp:04X} {unicodedata.name(ch,'?')} cat={unicodedata.category(ch)} got_bare={got} exp_bare={exp}")
print(f"tested {tested} chars x2 positions, mismatches: {bad}")
EOF
