import subprocess, json, unicodedata, random
EXE="/workspace/executable"
FIRST_OK={'Lu','Ll','Lm','Lo','Nl'}
REST_OK=FIRST_OK|{'Mn','Mc','Nd','Pc'}
random.seed(42)
cps=[cp for cp in range(0x20,0x2FFF) if not (0xD800<=cp<=0xDFFF)]
cps+=[cp for cp in [random.randrange(0x3000,0x110000) for _ in range(6000)] if not (0xD800<=cp<=0xDFFF)]
chars=sorted(set(chr(cp) for cp in cps))
def batch(keys):
    obj={k:i for i,k in keys}
    r=subprocess.run([EXE],input=json.dumps(obj,ensure_ascii=False).encode(),capture_output=True)
    res={}
    for line in r.stdout.decode().splitlines():
        if line.startswith('json.') or line.startswith('json["'):
            path,val=line.rsplit(' = ',1)
            res[int(val[:-1])]=line.startswith('json.')
    return res
tests=[]
for ch in chars:
    tests.append(('F',ch)); tests.append(('R','a'+ch))
mismF=set(); mismR=set()
B=2000
for i in range(0,len(tests),B):
    part=tests[i:i+B]
    res=batch([(idx,k) for idx,(t,k) in enumerate(part)])
    for idx,(t,k) in enumerate(part):
        got=res.get(idx)
        ch=k if t=='F' else k[1]
        exp=(ch in '$_' or unicodedata.category(ch) in (FIRST_OK if t=='F' else REST_OK))
        if got!=exp:
            (mismF if t=='F' else mismR).add(ord(ch))
def ranges(s):
    s=sorted(s); out=[]
    for cp in s:
        if out and cp==out[-1][1]+1: out[-1][1]=cp
        else: out.append([cp,cp])
    return ', '.join(f"U+{a:04X}" if a==b else f"U+{a:04X}..U+{b:04X}" for a,b in out)
print("FIRST-only mismatches:", ranges(mismF-mismR))
print("REST-only mismatches:", ranges(mismR-mismF))
print("BOTH mismatches:", ranges(mismF & mismR))
print("cats:", sorted(set(unicodedata.category(chr(cp)) for cp in (mismF|mismR))))
EOF
